      actions.className = 'sp-drawing-row-actions';
      const intervals = document.createElement('select');
      intervals.dataset.levelIntervals = index;
      intervals.setAttribute('aria-label', 'Interval visibility for horizontal line at ' + formatChartPrice(value));
      const rule = horizontalVisibility()[value];
