    let readingImage = false;
    let imageSelection = 0;
    const single = barsPattern || singleAnnotation(drawing.kind) || ['vertical', 'cross', 'horizontal-ray', 'text', 'price-label', 'arrow-up', 'arrow-down', 'arrow-left', 'arrow-right', 'anchored-vwap', 'anchored-volume-profile'].includes(drawing.kind);
    const arcSettings = isFibArcDrawing(drawing.kind);
    const fibChannel = drawing.kind === 'fib-channel';
