    modal.showModal();
    form.querySelector('[role="tab"][aria-selected="true"]').focus({preventScroll: true});
    const originalAnchor = label => (doubleCurve && label.startsWith('Control') || pattern && label.startsWith('Vertex'))
      ? drawing.points[Number(label.at(-1))] : drawing[label.toLowerCase()];
    const coordinatePrices = drawingCoordinateEditors(form, originalAnchor);
    const editedBricks = new Set();
