      ...(kind === 'bars-pattern' && Object.fromEntries(['patternMode', 'patternOpacity', 'patternMirror', 'patternFlip']
        .filter(name => Object.hasOwn(style, name)).map(name => [name, style[name]]))),
      ...(kind === 'text' && Object.fromEntries(['drawingTextSize', 'drawingTextBold', 'drawingTextItalic']
        .filter(name => Object.hasOwn(style, name)).map(name => [name, style[name]]))),
      ...(linkedAnnotation(kind) && Object.fromEntries(['noteTextColor', 'noteTextSize', 'noteBorderOpacity', 'noteBold', 'noteItalic', 'noteWrap', 'signpostEmojiEnabled', 'signpostEmoji', 'signpostEmojiColor']
        .filter(name => Object.hasOwn(style, name)).map(name => [name, style[name]]))),
      ...(Object.hasOwn(patternAnchors, kind) && Object.fromEntries(
        ['patternLabelColor', 'patternLabelOpacity', 'patternLabelSize', 'patternLabelBold', 'patternLabelItalic', 'elliottDegree', 'elliottShowWave']
          .filter(name => Object.hasOwn(style, name)).map(name => [name, style[name]]))),
      ...(styledCurveDrawing(kind) && Object.fromEntries(['curveExtension', 'curveStartMarker', 'curveEndMarker']
        .filter(name => Object.hasOwn(style, name)).map(name => [name, style[name]]))),
      ...(isVolumeProfile(kind) && volumeProfileOptions(style)),
