  function duplicateDrawings(drawings, openEditor = false, selectCopies = false) {
    if (!drawings.length) return;
    if (settings.drawings.length + drawings.length > drawingLimit) {
      levelMessage('There is room for ' + (drawingLimit - settings.drawings.length) + ' more drawings. Remove drawings or select fewer to duplicate.');
      return;
    }
    const before = drawingSnapshot();
    const index = settings.drawings.length;
    const copies = drawings.map(drawing => ({...structuredClone(drawing), locked: false}));
    settings.drawings.push(...copies);
    if (!save()) {
      settings.drawings.length = index;
      levelMessage('The browser could not save these drawing copies.');
      return;
    }
    recordDrawingEdit(before);
    if (!openEditor) selectedDrawings.clear();
    if (selectCopies) for (const copy of copies) selectedDrawings.add(copy);
    redrawDrawings();
    if (selectCopies) {
      levelMessage(copies.length === 1 ? 'Drawing pasted.' : copies.length + ' drawings pasted.');
      return;
    }
    if (!openEditor) {
      levelMessage(drawings.length + (drawings.length === 1 ? ' drawing copied.' : ' drawings copied.'));
      panel.querySelector('[data-find-drawing]').focus({preventScroll: true});
      return;
    }
    editDrawing(index);
    levelMessage('Drawing copied. Edit its coordinates to move it.');
  }

  function reorderDrawing(drawing, front) {
    const drawings = settings.drawings;
    const index = drawings.indexOf(drawing);
    const destination = front ? drawings.length - 1 : 0;
    if (index < 0 || index === destination || drawing.locked) return false;
    recordDrawingEdit();
    const remaining = drawings.filter(item => item !== drawing);
    settings.drawings = front ? [...remaining, drawing] : [drawing, ...remaining];
    redrawDrawings();
    levelMessage(front ? 'Drawing brought to front.' : 'Drawing sent to back.');
    return true;
  }

  function saveSharedDrawings() {
    if (!sharedChartView || barReplay || !hasDrawings()) return;
    try {
      const stored = JSON.parse(localStorage.getItem(key));
      const regular = chartSettings(stored);
      const symbol = chartSymbol();
      const active = !symbolSelection() || symbol === regular.symbol;
      const shapes = active ? regular.drawings : regular.instrumentDrawings?.[symbol] ?? [];
      const levels = active ? regular.levels : regular.instrumentLevels?.[symbol] ?? [];
      const savedShapes = new Set(shapes.map(drawing => JSON.stringify(drawing)));
      const additions = (settings.drawings ?? []).filter(drawing => !savedShapes.has(JSON.stringify(drawing)));
      const newLevels = settings.levels.filter(price => !levels.includes(price));
      const count = additions.length + newLevels.length;
      if (!count) return levelMessage('These drawings are already in your workspace.');
      if (shapes.length + additions.length > drawingLimit || levels.length + newLevels.length > drawingLimit) {
        return levelMessage('Your workspace has reached the drawing limit for this symbol.');
      }
      const next = {...stored};
      if (active) {
        next.drawings = [...shapes, ...additions];
        next.levels = [...levels, ...newLevels];
      } else {
        next.instrumentDrawings = {...regular.instrumentDrawings, [symbol]: [...shapes, ...additions]};
        next.instrumentLevels = {...regular.instrumentLevels, [symbol]: [...levels, ...newLevels]};
      }
      const visibility = {...regular.horizontalVisibilityBySymbol?.[symbol]};
      for (const price of newLevels) {
        const style = horizontalVisibility()[price];
        if (style) visibility[price] = style;
      }
      next.horizontalVisibilityBySymbol = {...regular.horizontalVisibilityBySymbol, [symbol]: visibility};
      localStorage.setItem(key, JSON.stringify(next));
      levelMessage(count === 1 ? '1 drawing copied to your workspace.' : count + ' drawings copied to your workspace.');
    } catch {
      levelMessage('Chart storage could not save these drawings.');
    }
  }

  function redrawDrawings() {
    showLevels();
    redrawKeepingViewport();
    save();
  }

  function moveHorizontalLevel(index, value) {
    const current = settings.levels[index];
    if (!Number.isFinite(current) || !Number.isFinite(value) || value <= 0 || settings.levels.includes(value)
        || horizontalVisibility()[current]?.locked) return false;
    recordDrawingEdit();
    const visibility = {...horizontalVisibility()};
    if (visibility[current]) {
      visibility[value] = visibility[current];
      delete visibility[current];
      setHorizontalVisibility(visibility);
    }
    settings.levels[index] = value;
    redrawDrawings();
    levelMessage('Horizontal level moved to ' + formatChartPrice(value) + '.');
    return true;
  }

  function addSingleAnchorLine(kind, anchor) {
    settings.drawings ??= [];
    if (settings.drawings.length >= drawingLimit) {
      levelMessage('The chart has reached its ' + drawingLimit + '-drawing limit. Remove a drawing to add another.');
      return;
    }
    recordDrawingEdit();
    const line = {...drawingStyleDefaults(kind), kind, start: anchor, end: {...anchor}};
    settings.drawings.push(line);
    selectLineStyle(line, undefined, true);
    redrawDrawings();
    levelMessage(kind === 'cross' ? 'Cross line added.' : 'Vertical line added.');
  }

  function horizontalLevelStyle(rule = {}) {
    return {
      color: /^#[a-f0-9]{6}$/i.test(rule.color ?? '') ? rule.color : horizontalLineDefaults.color,
      width: [1, 2, 3, 4].includes(rule.width) ? rule.width : horizontalLineDefaults.width,
      style: ['Solid', 'Dashed', 'Dotted'].includes(rule.style) ? rule.style : horizontalLineDefaults.style,
      opacity: Number.isInteger(rule.opacity) && rule.opacity >= 0 && rule.opacity <= 100
        ? rule.opacity : horizontalLineDefaults.opacity
    };
  }

  function openHorizontalLineStyle(price) {
    const index = settings.levels.indexOf(price);
    if (index < 0) return;
    setLinePlacement(false);
    if (settings.drawingToolbarHidden) panel.querySelector('[data-action="drawing-toolbar"]').click();
    panel.querySelector('[data-find-drawing]').value = '';
    panel.querySelector('[data-drawing-group-filter]').value = '';
    panel.querySelector('[data-drawing-visibility-filter]').value = '';
    filterDrawingList();
    panel.querySelector('.sp-chart-drawings').open = true;
    const style = panel.querySelector('[data-level-style="' + index + '"]');
    if (style) style.open = true;
    const control = style?.querySelector('[data-horizontal-style="color"]:enabled') ?? style?.querySelector('summary');
    control?.scrollIntoView({block: 'center'});
    control?.focus({preventScroll: true});
  }

  function addLevel(value, original) {
    if (!Number.isFinite(value) || value <= 0) {
      levelMessage('Enter a positive price.');
      return false;
    }
    if (settings.levels.includes(value)) {
      levelMessage('A horizontal level already uses that price.');
      return false;
    }
    if (settings.levels.length >= drawingLimit) {
      levelMessage('You can draw up to ' + drawingLimit + ' horizontal levels.');
      return false;
    }
    recordDrawingEdit();
    settings.levels.push(value);
    const rules = horizontalVisibility();
    const preferredStyle = settings.drawingStyleDefaults?.['horizontal-level'];
    if (original !== undefined && settings.levels.includes(original)) {
      setHorizontalVisibility({...rules, [value]: {...rules[original], locked: false, hidden: false}});
    } else if (preferredStyle) {
      setHorizontalVisibility({...rules, [value]: horizontalLevelStyle(preferredStyle)});
    }
    selectLineStyle(undefined, value, true);
    redrawDrawings();
    levelMessage('Horizontal level added at ' + formatChartPrice(value) + '.');
    return true;
  }

  let previousDateView;
  let initialChartHistory;
  let syncRecoveredChartSource;
  let goToDateRequest = 0;

  async function restoreSharedViewport(value, request) {
    const match = /^(\d{1,10}),(\d{1,10})$/.exec(value ?? '');
    if (request !== generation || !panel.open) return;
    const notice = panel.querySelector('[data-shared-range-status]');
    if (!match || tradeInterval(settings.interval)) {
      notice.textContent = 'This link contains an unsupported historical range.';
      return;
    }
    const [start, end] = match.slice(1).map(Number);
    if (start <= 0 || start > end || end > Date.now() / 1000) {
      notice.textContent = 'This link contains an invalid historical range.';
      return;
    }
    const interval = settings.interval;
    const type = settings.type;
    const current = () => request === generation && panel.open
      && settings.interval === interval && settings.type === type;
    await loadHistoryBefore(start, interval, current, undefined, dateHistorySearchOptions());
    if (!current()) return;
    const time = bar => bar.sourceTime ?? bar.time;
    const left = displayedBars.findIndex(bar => time(bar) >= start);
    const right = displayedBars.findLastIndex(bar => time(bar) <= end);
    if (!charts.length || left < 0 || right < left) {
      notice.textContent = olderHistoryFailure === request
        ? 'Earlier candles could not load. Reopen the shared link to retry.'
        : 'No loaded ' + broker.name + ' candles match the shared historical range.';
      return;
    }
    settings.range = {from: left - 0.75, to: right + 0.75};
    charts[0].timeScale().setVisibleLogicalRange(settings.range);
    if (time(displayedBars[left]) !== start || time(displayedBars[right]) !== end) {
      notice.textContent = 'Showing available candles in the shared range through '
        + chartTime(time(displayedBars[right]), true) + '.';
    }
  }

  async function goToDate(date, through, clock) {
    const message = panel.querySelector('[data-date-status]');
    const request = generation;
    const navigation = ++goToDateRequest;
    const pending = initialChartHistory;
    if (pending?.request === request) {
      message.textContent = 'Loading chart history before opening the selected date…';
      try {
        await pending.promise;
      } catch {
        if (request === generation && navigation === goToDateRequest && panel.open) {
          message.textContent = 'Chart history could not load. Retry history before opening a date.';
        }
        return;
      }
      if (request !== generation || navigation !== goToDateRequest || !panel.open) return;
    }
    if (!charts.length) {
      message.textContent = 'No candles are available for date navigation.';
      return;
    }
    const calendar = calendarInterval(settings.interval);
    const zone = calendar ? calendarZone() : displayZone();
    const midnight = Date.parse(date + 'T00:00:00Z');
    const lastMidnight = Date.parse((through ?? date) + 'T00:00:00Z');
    if (!Number.isFinite(midnight) || !Number.isFinite(lastMidnight)) return;
    if (lastMidnight < midnight) {
      message.textContent = 'Choose an end date on or after the start date.';
      return;
    }
    const timed = Boolean(clock) && !calendar;
    const start = timed ? localMinute(midnight, clock, zone) : localDayStart(midnight, zone);
    if (!Number.isFinite(start)) {
      message.textContent = 'That time does not exist in ' + zone + ' on the selected date.';
      return;
    }
    const end = localDayStart(lastMidnight + 86400000, zone);
    const timeOf = bar => bar.sourceTime ?? bar.time;
    const interval = settings.interval;
    const type = settings.type;
    const originalRange = charts[0].timeScale().getVisibleLogicalRange();
    const originalFirst = displayedBars[0]?.time;
    const isCurrent = () => navigation === goToDateRequest && request === generation
      && panel.open && settings.interval === interval && settings.type === type;
    await loadHistoryBefore(start, interval, isCurrent, () => {
      message.textContent = 'Loading earlier candles from ' + broker.name + '…';
    }, dateHistorySearchOptions());
    if (!isCurrent() || !charts.length) return;
    function indexAt(time) {
      let left = 0, right = displayedBars.length;
      while (left < right) {
        const middle = Math.floor((left + right) / 2);
        if (timeOf(displayedBars[middle]) < time) left = middle + 1;
        else right = middle;
      }
      return left;
    }
    let left = indexAt(start);
    const prior = displayedBars[left - 1];
    const overlapsStart = calendar || (timed && !tickInterval(interval) && settings.type !== 'Renko');
    if (overlapsStart && prior && timeOf(prior) < start && candleEnd(timeOf(prior), interval) > start) left--;
    const match = displayedBars[left];
    if (!match || timeOf(match) >= end) {
      const first = displayedBars[0];
      const last = displayedBars.at(-1);
      if (first && end <= timeOf(first)) {
        const earliest = ' Earliest candle: ' + chartTime(timeOf(first), true) + '.';
        message.textContent = olderHistoryFailure === request
          ? 'Earlier candles could not be loaded. Use Retry older candles or submit the date again.' + earliest
          : olderHistory.has(interval) ? 'That date is before the loaded history. Submit again to continue loading.' + earliest
            : 'The broker has no earlier candles for this interval.' + earliest;
      } else if (last && start > timeOf(last)) {
        message.textContent = 'That date is after the loaded history. Latest candle: ' + chartTime(timeOf(last), true) + '.';
      } else {
        message.textContent = 'No displayed bars for ' + (through ? 'that range' : 'that date') + ' (' + zone + ').';
      }
      return;
    }
    const scale = charts[0].timeScale();
    const current = scale.getVisibleLogicalRange();
    const span = current ? current.to - current.from : NaN;
    const width = Number.isFinite(span) && span > 0 ? span : 100;
    const from = Math.max(-5, left - Math.min(12, width / 4));
    const right = indexAt(end) - 1;
    const shift = displayedBars.findIndex(bar => bar.time === originalFirst);
    if (originalRange && shift >= 0 && settings.type === type) {
      previousDateView = {request, type, first: displayedBars[0].time,
        range: {from: originalRange.from + shift, to: originalRange.to + shift}};
      panel.querySelector('[data-action="restore-date-view"]').hidden = false;
    }
    settings.range = through
      ? {from: left - 0.75, to: Math.max(left, right) + 0.75}
      : {from, to: from + width};
    scale.setVisibleLogicalRange(settings.range);
    save();
    message.textContent = through
      ? 'Showing ' + (right - left + 1) + (right === left ? ' bar in range.' : ' bars in range.')
        + (timeOf(displayedBars[0]) > start && olderHistory.has(interval) ? ' Earlier candles may be available. Submit again to load more.' : '')
      : 'Showing ' + (calendar ? 'the period starting ' : '') + chartTime(timeOf(match), true) + '.';
  }

  function clearDataWindowPin() {
    dataWindowPinned = false;
    updateDataWindowPin();
  }

  function updateDataWindowPin() {
    const button = panel.querySelector('[data-action="pin-data-window"]');
    button.setAttribute('aria-pressed', String(dataWindowPinned));
    button.textContent = dataWindowPinned ? 'Unpin' : 'Pin';
    button.title = dataWindowPinned ? 'Resume following the crosshair' : 'Pin the inspected bar';
  }

  let cleanupLegendInspection, readHoveredChartBar;

  function clearCharts() {
    horizontalShortcutPrice = shortcutDrawingAnchor = undefined;
    cleanupLegendInspection?.();
    cleanupLegendInspection = readHoveredChartBar = undefined;
    renderedPriceSeries = undefined;
    renderedPriceContext = undefined;
    clearPriceRatioObserver?.();
    clearPriceRatioObserver = applyPriceRatio = undefined;
    activePaneResize = undefined;
    pendingViewportRedraw = false;
    activeChartPointers.clear();
    clearTimeout(chartWheelIdleTimer);
    chartWheelIdleTimer = undefined;
    chartBarAtPointer = undefined;
    stepDataWindow = undefined;
    drawingAtPointer = repaintDrawingSelection = nudgeSelectedDrawings = undefined;
    cancelDrawingDrag = undefined;
    tableCellAtPointer = undefined;
    levelAtPointer = undefined;
    updateLineStyle = undefined;
    repaintHighLow = undefined;
    repaintColumns = undefined;
    repaintBaseline = undefined;
    sessionBreakRepaints.clear();
    updateBaselineStyle = undefined;
    clearDrawingPreview = undefined;
    refreshDrawingPreviewModifiers = undefined;
    refreshRenderedVolumeProfiles = undefined;
    updateLastPrice = reconcileRecentBars = undefined;
    charts.forEach(chart => chart.remove());
    charts = [];
    syncPriceScaleButtons();
    stage.replaceChildren();
    stage.onpaste = null;
    comparisonCursorTime = undefined;
    for (const state of comparisons.values()) {
      state.render = state.applyStyle = state.paneReading = undefined;
      state.visibleBaseline = undefined;
      state.points = [];
    }
    displayedBars = [];
    displayedStudies = [];
    panel.querySelector('[data-action="export-chart"]').disabled = true;
    panel.querySelector('[data-action="export-loaded-chart"]').disabled = true;
    panel.querySelector('[data-action="save-chart-image"]').disabled = true;
    panel.querySelector('[data-action="copy-chart-image"]').disabled = true;
    panel.querySelector("[data-date-status]").textContent = "";
    panel.querySelector("[data-study-status]").textContent = "";
    const ranges = panel.querySelector('.sp-shadow-table');
    ranges.replaceChildren();
    ranges.closest('.sp-reference-studies').hidden = true;
  }

  function parseIntervalShortcut(text) {
    if (/^1,000\s*(?:t|ticks?)$/i.test(text.trim())) return '1000T';
    const match = /^([1-9]\d{0,3})\s*([a-z]*)$/i.exec(text.trim());
    if (!match) return undefined;
    const [, length, unit] = match;
    if (unit === 'M') return length + 'M';
    const suffix = unit.toLowerCase();
    if (/^(?:h|hours?)$/.test(suffix)) return String(Number(length) * 60);
    if (/^(?:y|years?)$/.test(suffix)) return String(Number(length) * 12) + 'M';
    if (/^(?:m|min(?:ute)?s?)?$/.test(suffix)) return length;
    if (/^(?:months?)$/.test(suffix)) return length + 'M';
    if (/^(?:d|days?)$/.test(suffix)) return length + 'D';
    if (/^(?:w|weeks?)$/.test(suffix)) return length + 'W';
    if (/^(?:s|sec(?:ond)?s?)$/.test(suffix)) return length + 'S';
    if (/^(?:t|ticks?)$/.test(suffix)) return length + 'T';
  }

  function sourceInterval(value) {
    return broker.yahoo ? yahooSourceInterval(value) : !tradeInterval(value) || deltaTradeSymbol(chartSymbol());
  }

  function intervalUnavailableReason(value) {
    if (!sourceInterval(value)) return 'Unavailable from ' + broker.name;
    if (settings.type === 'Renko' && tickInterval(value)) return 'Tick intervals are unavailable on Renko';
    return '';
  }

  function restoreIntervalList(storageName, legacyField) {
    const listed = values => Array.isArray(values)
      ? values.filter(value => typeof value === 'string' && validInterval(value)) : [];
    const storageKey = chartStoragePrefix + storageName;
    const current = settings[legacyField];
    const migrated = new Set(listed(current));
    try {
      const stored = JSON.parse(localStorage.getItem(storageKey));
      if (Array.isArray(stored)) return [...new Set(listed(stored))];
    } catch {}
    try {
      for (const candidate of Object.keys(localStorage)) {
        if (!candidate.startsWith(chartStoragePrefix) || candidate === key || candidate === storageKey) continue;
        try {
          const saved = JSON.parse(localStorage.getItem(candidate));
          for (const interval of listed(saved?.[legacyField])) migrated.add(interval);
        } catch {}
      }
    } catch {}
    return migrated.size || Array.isArray(current) ? [...migrated] : undefined;
  }

  function saveIntervalList(storageName, values) {
    if (sharedChartView || !Array.isArray(values)) return;
    try {
      localStorage.setItem(chartStoragePrefix + storageName, JSON.stringify(values));
    } catch {}
  }

  function renderIntervals() {
    const active = intervalLabel(settings.interval);
    const activeLabel = panel.querySelector('[data-active-interval]');
    const intervalSummary = activeLabel.closest('summary');
    activeLabel.textContent = active;
    intervalSummary.title = 'Chart interval: ' + active;
    intervalSummary.setAttribute('aria-label', intervalSummary.title);
    const pinned = settings.pinnedIntervals ?? defaultPinnedIntervals;
    const hidden = new Set(settings.hiddenIntervals ?? []);
    const validFavorites = [...new Set(pinned)].filter(value => typeof value === 'string' && validInterval(value) && !hidden.has(value));
    const availableFavorites = validFavorites.filter(value => sourceInterval(value)
      && (settings.type !== 'Renko' || !tickInterval(value)));
    intervalSummary.toggleAttribute('data-active-pinned', availableFavorites.includes(settings.interval));
    const pinnedGroup = panel.querySelector('[data-pinned-intervals]');
    const focusedInterval = pinnedGroup.contains(document.activeElement) ? document.activeElement.dataset.interval : undefined;
    pinnedGroup.replaceChildren(...availableFavorites.map(value => {
      const button = document.createElement('button');
      button.type = 'button';
      button.dataset.interval = value;
      button.textContent = intervalLabel(value);
      button.draggable = true;
      button.title = intervalLabel(value) + ' · Drag or use ' + (usesMacKeys ? 'Option' : 'Alt') + '+←/→ to reorder';
      button.setAttribute('aria-keyshortcuts', 'Alt+ArrowLeft Alt+ArrowRight');
      button.setAttribute('aria-pressed', String(value === settings.interval));
      return button;
    }));
    if (focusedInterval) [...pinnedGroup.children].find(button => button.dataset.interval === focusedInterval)?.focus({preventScroll: true});
    const activeFavorite = pinnedGroup.querySelector('[aria-pressed="true"]');
    if (activeFavorite) requestAnimationFrame(() => {
      if (!activeFavorite.isConnected || !pinnedGroup.clientWidth) return;
      const strip = pinnedGroup.getBoundingClientRect();
      const favorite = activeFavorite.getBoundingClientRect();
      if (favorite.left < strip.left) pinnedGroup.scrollLeft += favorite.left - strip.left;
      else if (favorite.right > strip.right) pinnedGroup.scrollLeft += favorite.right - strip.right;
    });
    const pin = panel.querySelector('[data-action="pin-interval"]');
    const isPinned = pinned.includes(settings.interval);
    pin.textContent = (isPinned ? 'Unpin ' : 'Pin ') + active;
    const customForm = panel.querySelector('[data-custom-interval]');
    customForm.hidden = Boolean(broker.yahoo && !broker.customMinutesMax && !broker.customCalendar);
    const supportsTradeIntervals = sourceInterval('1S');
    const unit = customForm.elements.unit;
    for (const option of unit.options) {
      option.disabled = option.value === 'S' ? !supportsTradeIntervals
        : Boolean(broker.yahoo && (['1', '60'].includes(option.value) ? !broker.customMinutesMax : !broker.customCalendar));
    }
    if (unit.selectedOptions[0]?.disabled) {
      unit.value = [...unit.options].find(option => !option.disabled)?.value ?? '1';
      unit.dispatchEvent(new Event('change'));
    }
    panel.querySelector('[data-trade-coverage]').textContent = broker.yahoo
      ? 'Yahoo Finance provides historical OHLC. Unavailable intervals are shown dimmed. Refresh to fetch newer candles.'
      : supportsTradeIntervals
        ? 'Seconds and tick bars start with trades captured by the Delta WebSocket. Earlier bars are unavailable.'
        : 'Seconds and tick intervals are unavailable for ' + chartSymbol() + ' from ' + broker.name + '.';
    const intervalButton = (interval, label, removable = false, hidable = false) => {
      const unavailable = intervalUnavailableReason(interval);
      const available = !unavailable;
      const favorite = pinned.includes(interval);
      const favoriteTitle = (favorite ? 'Remove ' + label + ' from' : 'Add ' + label + ' to') + ' favorites';
      return '<span class="sp-interval-option"' + (unavailable ? ' title="' + esc(unavailable) + '"' : '')
        + '><button type="button" data-interval="' + interval + '"'
        + (available ? '' : ' disabled aria-label="' + esc(label + ' · ' + unavailable) + '"')
        + ' aria-pressed="' + String(interval === settings.interval) + '">' + label + '</button>'
        + (available || favorite ? '<button type="button" data-action="pin-interval" data-pin-value="' + interval
          + '" aria-label="Favorite ' + label + '" title="' + favoriteTitle + '" aria-pressed="' + favorite + '">'
          + (favorite ? '★' : '☆') + '</button>' : '')
        + (removable ? '<button type="button" data-action="remove-custom-interval" data-custom-value="' + interval
          + '" aria-label="Remove custom interval ' + label + '" title="Remove custom interval">×</button>' : '')
        + (hidable ? '<button type="button" data-action="hide-standard-interval" data-visibility-interval="' + interval
          + '" aria-label="Hide ' + label + ' interval" title="Hide interval">×</button>' : '') + '</span>';
    };
    const standardIntervals = new Set();
    const favoriteIntervals = new Set(validFavorites);
    const sections = intervalGroups.map(([title, unit, values]) => {
      const buttons = values.map(value => {
        const interval = String(unit === 'h' ? value * 60 : unit === 'm' ? value : String(value) + unit);
        standardIntervals.add(interval);
        return favoriteIntervals.has(interval) || hidden.has(interval) ? '' : intervalButton(interval, intervalLabel(interval), false, true);
      }).join('');
      return buttons ? '<section><small>' + title + '</small><div>' + buttons + '</div></section>' : '';
    });
    const savedCustom = new Set(settings.customIntervals ?? []);
    const custom = [...new Set([...savedCustom, settings.interval])].filter(value =>
      validInterval(value) && !standardIntervals.has(value) && !favoriteIntervals.has(value));
    if (custom.length) sections.push('<section><small>Custom</small><div>' + custom.map(value =>
      intervalButton(value, intervalLabel(value), savedCustom.has(value))).join('') + '</div></section>');
    if (validFavorites.length) {
      sections.unshift('<section data-interval-favorites><small>Favorites</small><div>'
        + validFavorites.map(value => intervalButton(value, intervalLabel(value),
          savedCustom.has(value) && !standardIntervals.has(value), standardIntervals.has(value))).join('')
        + '</div></section>');
    }
    const hiddenStandard = [...standardIntervals].filter(value => hidden.has(value));
    if (hiddenStandard.length) sections.push('<details data-hidden-intervals><summary>Hidden intervals (' + hiddenStandard.length
      + ')</summary><div>' + hiddenStandard.map(value => '<button type="button" data-action="restore-standard-interval" data-visibility-interval="'
        + value + '" aria-label="Restore ' + intervalLabel(value) + ' interval">' + intervalLabel(value) + ' +</button>').join('') + '</div></details>');
    const availableHours = requestedHourIntervals.filter(value => sourceInterval(value) && !hidden.has(value));
    const canPinHours = availableHours.some(value => !pinned.includes(value));
    if (canPinHours) sections.unshift('<button type="button" data-action="pin-long-hours">Pin '
      + availableHours.map(intervalLabel).join(', ') + '</button>');
    panel.querySelector('[data-interval-options]').innerHTML = sections.join('');
  }

  function selectTypedInterval(value) {
    if (!validInterval(value) || intervalUnavailableReason(value)) return;
    const preset = intervalGroups.some(([, unit, values]) => values.some(length =>
      value === String(unit === 'h' ? length * 60 : unit === 'm' ? length : String(length) + unit)));
    if (!preset && !settings.customIntervals?.includes(value)) {
      settings.customIntervals = [...(settings.customIntervals ?? []), value];
      saveIntervalList('custom-intervals', settings.customIntervals);
    }
    return selectInterval(value);
  }

  function selectInterval(value) {
    const menu = panel.querySelector('[data-interval-picker]');
    const returnFocus = menu.contains(document.activeElement);
    menu.open = false;
    if (returnFocus) menu.querySelector('summary').focus({preventScroll: true});
    if (!sourceInterval(value)) return;
    if (tickInterval(value) && settings.type === 'Renko') return;
    if (barReplay) {
      if (value !== settings.interval) return switchReplayInterval(value);
      return;
    }
    const changed = value !== settings.interval;
    if (changed) {
      const range = charts[0]?.timeScale().getVisibleLogicalRange();
      const pinLeft = settings.pinLeftOnInterval === true;
      const anchor = range && (pinLeft ? viewportAnchor(range, false, false)
        : viewportAnchor({from: Math.floor(range.to), to: range.to}));
      if (!pinLeft && anchor && !anchor.latest && Number.isFinite(anchor.time)) {
        // Preserve the viewed candle through its last instant when changing resolutions.
        const end = candleEnd(anchor.time, settings.interval);
        const next = displayedBars[anchor.index + 1];
        const nextTime = next?.sourceTime ?? next?.time;
        const boundary = Number.isFinite(nextTime) && nextTime > anchor.time ? Math.min(end, nextTime) : end;
        if (Number.isFinite(boundary) && boundary > anchor.time) anchor.time = boundary - 1;
      }
      restoredViewAnchor = anchor && {...anchor, intervalChanged: true, pinLeft};
      if (anchor) settings.range = range;
      else delete settings.range;
      settings.interval = value;
      showLevels();
    }
    setControls();
    save();
    if (changed) return load();
  }

  const priceScaleModes = { linear: 'Normal', log: 'Logarithmic', percent: 'Percentage', indexed: 'IndexedTo100' };

  function crosshairMode() {
    const modes = window.LightweightCharts.CrosshairMode;
    if (settings.cursor === 'pointer') return modes.Hidden;
    return settings.snapCrosshair === true ? modes.Magnet : modes.Normal;
  }

  function sharedComparisonScale() {
    return Boolean(activeComparisons().some(state => comparisonMode(state.symbol) === 'shared')
      && settings.type !== 'Renko' && !tradeInterval(settings.interval));
  }

  function priceScaleMode() {
    return window.LightweightCharts.PriceScaleMode[sharedComparisonScale()
      ? 'Normal' : priceScaleModes[settings.scale] ?? 'Normal'];
  }

  function drawingFavoritesKey() {
    return chartStoragePrefix + 'drawing-favorites';
  }

  let sharedDrawingFavorites;

  function drawingFavorites() {
    if (sharedChartView && sharedDrawingFavorites) return sharedDrawingFavorites;
    try {
      const saved = localStorage.getItem(drawingFavoritesKey())
        ?? localStorage.getItem('sector-pulse-chart-drawing-favorites');
      const favorites = JSON.parse(saved);
      if (Array.isArray(favorites)) return favorites;
    } catch {}
    return [];
  }

  function saveDrawingFavorites(favorites) {
    if (sharedChartView) sharedDrawingFavorites = favorites;
    else {
      try { localStorage.setItem(drawingFavoritesKey(), JSON.stringify(favorites)); } catch { return false; }
    }
    return true;
  }

  function updateDrawingFavoriteStar(star, selected) {
    star.textContent = selected ? '★' : '☆';
    star.title = selected ? 'Remove from favorites' : 'Add to favorites';
    star.setAttribute('aria-pressed', String(selected));
  }

  function drawingDockBounds(dock, bottom = 0) {
    return {
      width: Math.max(0, dock.offsetParent.clientWidth - dock.offsetWidth),
      height: Math.max(0, dock.offsetParent.clientHeight - dock.offsetHeight - bottom)
    };
  }

  function drawingDockOffset(dock, x, y, bottom = 0) {
    const {width, height} = drawingDockBounds(dock, bottom);
    return {x: Math.max(0, Math.min(1, x / Math.max(1, width))),
      y: Math.max(0, Math.min(1, y / Math.max(1, height)))};
  }

  function bindCompactDrawingControls(root, media = matchMedia('(max-width: 760px)')) {
    const rail = root.querySelector('.sp-chart-tools');
    if (!rail || rail.querySelector('[data-compact-drawing-controls]')) return;
    const controls = [...rail.querySelectorAll(':scope > [data-action="measure-chart"], :scope > [data-drawing="zoom-area"], :scope > [data-drawing="eraser"], :scope > [data-action="keep-drawing"], :scope > [data-action="lock-all-drawings"]')];
    if (!controls.length) return;
    const slots = controls.map(control => {
      const slot = document.createComment('drawing control position');
      control.before(slot);
      const label = document.createElement('span');
      label.className = 'sp-chart-compact-control-label';
      label.textContent = control.getAttribute('aria-label') || control.title;
      control.append(label);
      return {control, slot};
    });
    const group = document.createElement('details');
    group.className = 'sp-chart-layouts sp-chart-compact-controls';
    group.dataset.compactDrawingControls = '';
    const summary = document.createElement('summary');
    summary.setAttribute('aria-label', 'More drawing controls');
    summary.title = 'More drawing controls';
    summary.innerHTML = chartToolbarIcon('M4 4h6v6H4zM14 4h6v6h-6zM4 14h6v6H4zM14 14h6v6h-6z');
    const menu = document.createElement('div');
    menu.className = 'sp-chart-layout-menu';
    group.append(summary, menu);
    rail.insertBefore(group, rail.querySelector('.sp-chart-magnet-control'));
    const update = () => {
      const active = root.ownerDocument.activeElement;
      const focused = controls.some(control => control === active || control.contains(active)) ? active : null;
      group.hidden = !media.matches;
      for (const {control, slot} of slots) {
        if (media.matches) menu.append(control);
        else slot.after(control);
      }
      group.open = Boolean(focused && media.matches);
      if (focused) focused.focus({preventScroll: true});
    };
    group.addEventListener('click', event => {
      const control = event.target.closest('button');
      if (controls.includes(control) && (control.dataset.action === 'measure-chart' || control.dataset.drawing)) group.open = false;
    });
    group.addEventListener('keydown', event => {
      if (event.key !== 'Escape' || !group.open) return;
      event.preventDefault();
      event.stopPropagation();
      group.open = false;
      summary.focus({preventScroll: true});
    });
    rail.addEventListener('toggle', event => {
      const details = event.target;
      if (!(details instanceof HTMLDetailsElement) || !details.open) return;
      if (details === group) {
        for (const other of rail.querySelectorAll('details[open]')) {
          if (other !== group && !group.contains(other)) other.open = false;
        }
      } else if (!group.contains(details)) group.open = false;
    }, true);
    media.addEventListener('change', update);
    update();
  }

  function bindDrawingDockHandle(handle, dock, move, reset) {
    let drag;
    const offset = () => {
      const bounds = dock.getBoundingClientRect();
      const area = dock.offsetParent.getBoundingClientRect();
      return {left: bounds.left - area.left, top: bounds.top - area.top};
    };
    handle.addEventListener('pointerdown', event => {
      if (event.button !== 0 || !dock.offsetParent) return;
      event.preventDefault();
      handle.focus({preventScroll: true});
      handle.setPointerCapture(event.pointerId);
      drag = {...offset(), pointer: event.pointerId, x: event.clientX, y: event.clientY};
    });
    handle.addEventListener('pointermove', event => {
      if (drag?.pointer !== event.pointerId || !dock.offsetParent) return;
      move(drag.left + event.clientX - drag.x, drag.top + event.clientY - drag.y);
    });
    handle.addEventListener('lostpointercapture', () => {
      if (!drag) return;
      drag = undefined;
      save();
    });
    handle.addEventListener('keydown', event => {
      const direction = {ArrowLeft: [-16, 0], ArrowRight: [16, 0], ArrowUp: [0, -16], ArrowDown: [0, 16]}[event.key];
      if (!(direction || event.key === 'Home' && reset) || !dock.offsetParent) return;
      event.preventDefault();
      event.stopPropagation();
      if (direction) {
        const {left, top} = offset();
        move(left + direction[0], top + direction[1]);
      } else reset();
      save();
    });
  }

  function drawingStyleToolbarBottom() {
    return panel.querySelector('.sp-chart-footer').offsetHeight + 8;
  }

  function pricePaneDockPlacement(dock, defaultBottom, clearance, minimumVisible) {
    const price = stage.querySelector('.sp-chart-price')?.getBoundingClientRect();
    if (!price || !stage.querySelector('.sp-chart-pane')) return {bottom: defaultBottom, offscreen: false};
    const viewport = stage.getBoundingClientRect();
    const bottom = Math.min(viewport.bottom, price.bottom);
    const top = Math.max(viewport.top, price.top);
    const containerBottom = dock.closest('.sp-chart-main').getBoundingClientRect().bottom;
    return {bottom: Math.max(defaultBottom, containerBottom - bottom + clearance), offscreen: bottom - top < minimumVisible};
  }

  function positionDrawingStyleToolbar(toolbar) {
    const position = settings.drawingStylePosition;
    const positioned = Number.isFinite(position?.x) && Number.isFinite(position?.y);
    toolbar.toggleAttribute('data-positioned', positioned);
    if (!positioned && !toolbar.hidden) {
      const dock = panel.querySelector('[data-drawing-shortcut-dock][data-floating]:not([data-positioned])');
      const clearance = dock?.offsetHeight ? dock.offsetHeight + 20 : 12;
      const {bottom, offscreen} = pricePaneDockPlacement(toolbar, 110, clearance, clearance + toolbar.offsetHeight + 4);
      toolbar.style.setProperty('--drawing-style-bottom', bottom + 'px');
      toolbar.toggleAttribute('data-price-pane-offscreen', offscreen);
    } else toolbar.removeAttribute('data-price-pane-offscreen');
    if (positioned && toolbar.offsetParent) {
      const {width, height} = drawingDockBounds(toolbar, drawingStyleToolbarBottom());
      toolbar.style.left = Math.min(1, Math.max(0, position.x)) * width + 'px';
      toolbar.style.top = Math.min(1, Math.max(0, position.y)) * height + 'px';
    } else {
      toolbar.style.removeProperty('left');
      toolbar.style.removeProperty('top');
    }
  }

  function positionDrawingFavorites() {
    const dock = panel.querySelector('[data-drawing-shortcut-dock]');
    const position = settings.drawingFavoritesPosition;
    const positioned = settings.floatDrawingFavorites && Number.isFinite(position?.x) && Number.isFinite(position?.y);
    dock.toggleAttribute('data-positioned', !!positioned);
    const footerHeight = panel.querySelector('.sp-chart-footer').offsetHeight;
    const {bottom, offscreen} = !positioned && settings.floatDrawingFavorites
      ? pricePaneDockPlacement(dock, footerHeight + 38, 12, 52)
      : {bottom: footerHeight + 38, offscreen: false};
    dock.toggleAttribute('data-price-pane-offscreen', offscreen);
    dock.style.setProperty('--drawing-dock-bottom', bottom + 'px');
    if (positioned && dock.offsetParent) {
      dock.style.left = Math.min(1, Math.max(0, position.x)) * Math.max(0, dock.offsetParent.clientWidth - dock.offsetWidth) + 'px';
      dock.style.top = Math.min(1, Math.max(0, position.y)) * Math.max(0, dock.offsetParent.clientHeight - dock.offsetHeight) + 'px';
    } else {
      dock.style.removeProperty('left');
      dock.style.removeProperty('top');
    }
    positionDrawingStyleToolbar(panel.querySelector('.sp-drawing-style-toolbar'));
  }

