  function updateChartVenue() {
    const symbol = chartSymbol();
    const venue = motilalSymbolSelection ? symbol.split(':').at(-2) ?? broker.venue
      : fyersSymbolSelection ? symbol.split(':')[0]
      : dhanSymbolSelection && symbol.startsWith('IDX_I:') && symbol !== dhanDefaultSymbol ? settings.dhanIndexExchanges?.[symbol] ?? 'Index'
      : dhanSymbolSelection ? /^(NSE|BSE|MCX)_/.exec(symbol)?.[1] ?? broker.venue
      : broker.venue;
    panel.querySelector('[data-chart-legend-venue]').textContent =
      [intervalLabel(settings.interval), venue === broker.name || deltaSymbolSelection ? broker.name : venue + ' · ' + broker.name].filter(Boolean).join(' · ');
  }

