      instruments.querySelector('[data-chart-active-instrument]').textContent = dhanSymbolSelection
        ? dhanPineInstruments.get(chartSymbol())?.symbol || settings.dhanSymbolLabel || (chartSymbol() === dhanDefaultSymbol ? 'NIFTY' : chartSymbol()) : motilalSymbolSelection ? motilalPineInstruments.get(chartSymbol())?.symbol || settings.motilalSymbolLabel || chartSymbol() : chartDisplayTicker();
      if (!instruments.open && !serverSymbolSelection()) renderSymbolResults();
