    panel.querySelector('[data-kagi-reversal]').value = kagiFixedReversal();
    panel.querySelector('[data-kagi-atr]').value = kagiAtrLength();
    panel.querySelector('[data-kagi-percent]').value = kagiPercent();
    panel.querySelector('[data-kagi-projection]').checked = settings.kagiProjection !== false;
    for (const label of panel.querySelectorAll('[data-kagi-input]')) label.hidden = label.dataset.kagiInput !== kagiMethod();
    panel.querySelector('[data-line-break-setting]').hidden = settings.type !== 'Line break';
    panel.querySelector('[data-line-break-count]').value = lineBreakCount();
    panel.querySelector('[data-line-break-projection-setting]').hidden = settings.type !== 'Line break';
    panel.querySelector('[data-line-break-projection]').checked = settings.lineBreakProjection !== false;
    const useAtr = settings.brickMethod === 'atr';
    const usePercent = settings.brickMethod === 'percent';
    panel.querySelector('[data-brick-method]').value = useAtr ? 'atr' : usePercent ? 'percent' : 'fixed';
    panel.querySelector('[data-fixed-brick]').hidden = useAtr || usePercent;
    panel.querySelector('[data-percent-brick]').hidden = !usePercent;
    panel.querySelector('[data-atr-brick]').hidden = !useAtr;
    for (const [attribute, value] of [
      ['data-brick-size', settings.size],
      ['data-brick-atr', settings.brickAtrLength],
      ['data-brick-percent', settings.brickPercent ?? 1]
    ]) {
      const input = panel.querySelector('[' + attribute + ']');
      if (input === document.activeElement) continue;
      input.value = value;
      input.setCustomValidity('');
    }
    panel.querySelector('[data-renko-source]').value = settings.renkoSource === 'ohlc' ? 'ohlc' : 'close';
    panel.querySelector('[data-renko-wicks]').checked = renkoWicksVisible();
